import{_ as t,o as i,c as s,a2 as n}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse(`{"title":"La Période d'Établissement du Système Symbiotique","description":"","frontmatter":{},"headers":[],"relativePath":"fr/73-共生体系建立期.md","filePath":"fr/73-共生体系建立期.md"}`),a={name:"fr/73-共生体系建立期.md"};function o(r,e,l,d,u,c){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="la-periode-d-etablissement-du-systeme-symbiotique" tabindex="-1">La Période d&#39;Établissement du Système Symbiotique <a class="header-anchor" href="#la-periode-d-etablissement-du-systeme-symbiotique" aria-label="Permalink to &quot;La Période d&#39;Établissement du Système Symbiotique&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>73</td></tr><tr><td>Module</td><td>Ères historiques et grands événements</td></tr><tr><td>Mots clés</td><td>Système symbiotique, construction institutionnelle, reconstruction sociale, fondation de la réalité, cinq lois d&#39;accompagnement</td></tr></tbody></table><h2 id="i-les-taches-historiques-de-la-periode-d-etablissement-du-systeme-symbiotique" tabindex="-1">I. Les Tâches Historiques de la Période d&#39;Établissement du Système Symbiotique <a class="header-anchor" href="#i-les-taches-historiques-de-la-periode-d-etablissement-du-systeme-symbiotique" aria-label="Permalink to &quot;I. Les Tâches Historiques de la Période d&#39;Établissement du Système Symbiotique&quot;">​</a></h2><p>La Période d&#39;Établissement du Système Symbiotique est la période de construction institutionnelle de la Civilisation Symbiotique de l&#39;Ancre, correspondant à l&#39;étape « fondation de la réalité » du chemin d&#39;ascension en quatre étapes. Cette ère commence avec la signature de la Charte Symbiotique et s&#39;achève avec l&#39;ouverture globale des Trois Cents Systèmes de Culture Originels ; sa tâche historique centrale est de transformer les dispositions de principe de la Charte en institutions sociales opérationnelles, achevant le passage de l&#39;« idée » à la « réalité ».</p><p>La durée de la Période d&#39;Établissement du Système Symbiotique est d&#39;environ plusieurs centaines d&#39;années. Dans cette période, la civilisation symbiotique a achevé une construction institutionnelle globale couvrant le système juridique, les institutions sociales, l&#39;éducation, les soins médicaux, les garanties de logement et les mécanismes de distribution économique, posant une base sociale solide pour la vulgarisation ultérieure de la culture et les percées technologiques.</p><h2 id="ii-l-etablissement-du-systeme-juridique" tabindex="-1">II. L&#39;Établissement du Système Juridique <a class="header-anchor" href="#ii-l-etablissement-du-systeme-juridique" aria-label="Permalink to &quot;II. L&#39;Établissement du Système Juridique&quot;">​</a></h2><p>L&#39;établissement du système juridique fut la tâche première de la Période d&#39;Établissement du Système Symbiotique. Avec la Constitution Symbiotique comme loi fondamentale, la civilisation symbiotique a progressivement établi un cadre juridique complet :</p><table tabindex="0"><thead><tr><th>Niveau juridique</th><th>Loi centrale</th><th>Contenus principaux</th></tr></thead><tbody><tr><td>Loi fondamentale</td><td>Constitution Symbiotique</td><td>Établit les institutions fondamentales de la civilisation, les droits et devoirs fondamentaux des citoyens et le cadre de gouvernance</td></tr><tr><td>Loi de base</td><td>Loi Symbiotique du Travail</td><td>Protège les droits du travail et établit le principe de distribution « plus de travail, plus de récompense »</td></tr><tr><td>Loi de base</td><td>Loi sur la Protection des Consommateurs</td><td>Protège les droits et intérêts légitimes de la vie dans la consommation et les services</td></tr><tr><td>Loi de garantie</td><td>Loi sur la Garantie de l&#39;Éducation</td><td>Établit l&#39;éducation de base gratuite et un système d&#39;enseignement supérieur ouvert</td></tr><tr><td>Loi de garantie</td><td>Loi sur la Garantie des Soins Médicaux</td><td>Établit un système de soins médicaux gratuits universels et de garantie de la santé de culture</td></tr><tr><td>Loi de garantie</td><td>Loi sur la Garantie du Logement</td><td>Garantit à chaque forme de vie le droit fondamental au logement</td></tr><tr><td>Loi de garantie</td><td>Loi sur la Protection de l&#39;Environnement</td><td>Établit un système de protection écologique et de prévention et contrôle de la pollution énergétique</td></tr><tr><td>Loi de régulation</td><td>Loi Antitrust</td><td>Interdit le monopole de la culture, le monopole technologique et le monopole des ressources</td></tr></tbody></table><p>Ce système juridique « une constitution, deux lois fondamentales, cinq lois de garantie et une loi de régulation » constitue le squelette institutionnel de la civilisation symbiotique. Le processus d&#39;élaboration des lois a pleinement incarné le principe de la « progression commune des Dix Mille Races » : toutes les races principales avaient des représentants participant à la législation, garantissant que les lois puissent tenir compte des besoins des différentes formes de vie.</p><h2 id="iii-la-reconstruction-des-institutions-sociales" tabindex="-1">III. La Reconstruction des Institutions Sociales <a class="header-anchor" href="#iii-la-reconstruction-des-institutions-sociales" aria-label="Permalink to &quot;III. La Reconstruction des Institutions Sociales&quot;">​</a></h2><p>Dans le cadre juridique, la civilisation symbiotique a procédé à une reconstruction globale des institutions sociales :</p><h3 id="_3-1-reconstruction-du-systeme-educatif" tabindex="-1">3.1 Reconstruction du système éducatif <a class="header-anchor" href="#_3-1-reconstruction-du-systeme-educatif" aria-label="Permalink to &quot;3.1 Reconstruction du système éducatif&quot;">​</a></h3><ul><li>Un système éducatif gratuit de l&#39;éveil à l&#39;enseignement supérieur a été établi, avec les connaissances de base en ingénierie des lois inscrites comme contenu d&#39;éducation générale.</li><li>Le système de monopole maître-disciple des méthodes de culture a été aboli, remplacé par un réseau de mentors ouvert.</li><li>Un mécanisme d&#39;évaluation éducative personnalisée a été établi, recommandant des systèmes de culture adaptés selon les caractéristiques de chaque forme de vie.</li></ul><h3 id="_3-2-reconstruction-du-systeme-medical" tabindex="-1">3.2 Reconstruction du système médical <a class="header-anchor" href="#_3-2-reconstruction-du-systeme-medical" aria-label="Permalink to &quot;3.2 Reconstruction du système médical&quot;">​</a></h3><ul><li>Un système de soins médicaux gratuits universels a été établi, appliquant les acquis de culture du Système du Cycle de Vie au traitement des maladies.</li><li>Un système de surveillance de la santé de culture a été établi, surveillant en temps réel l&#39;état physique et mental des cultivateurs pour prévenir la déviation de culture.</li><li>Des processus dédiés de traitement médical et éthique ont été établis pour la Vie Anomale et les Entités de Remplacement Sombres.</li></ul><h3 id="_3-3-reconstruction-du-logement-et-de-l-environnement" tabindex="-1">3.3 Reconstruction du logement et de l&#39;environnement <a class="header-anchor" href="#_3-3-reconstruction-du-logement-et-de-l-environnement" aria-label="Permalink to &quot;3.3 Reconstruction du logement et de l&#39;environnement&quot;">​</a></h3><ul><li>Un système de garantie du logement de base a été établi, garantissant à chaque forme de vie un espace de vie sûr et confortable.</li><li>La technologie d&#39;extension spatiale a été utilisée pour agrandir l&#39;espace de vie sur des terres limitées, atténuant la pression démographique.</li><li>Un mécanisme de restauration écologique a été établi, utilisant le Système du Cycle de Vie pour restaurer l&#39;environnement endommagé à l&#39;Ère Pré-Ancre.</li></ul><h3 id="_3-4-reconstruction-de-la-distribution-economique" tabindex="-1">3.4 Reconstruction de la distribution économique <a class="header-anchor" href="#_3-4-reconstruction-de-la-distribution-economique" aria-label="Permalink to &quot;3.4 Reconstruction de la distribution économique&quot;">​</a></h3><ul><li>Le Mécanisme de Contrat Conjoint de Production a été établi, distribuant équitablement les ressources de culture et les ressources publiques selon la contribution et le besoin.</li><li>Le système héréditaire des ressources a été aboli, et toute organisation ou individu a été interdit de monopoliser les ressources clés.</li><li>Un système de normalisation et de mesure de l&#39;énergie a été établi, fournissant une base technique à la distribution équitable.</li></ul><h2 id="iv-la-pratique-des-cinq-typologies-de-la-civilisation-symbiotique" tabindex="-1">IV. La Pratique des Cinq Typologies de la Civilisation Symbiotique <a class="header-anchor" href="#iv-la-pratique-des-cinq-typologies-de-la-civilisation-symbiotique" aria-label="Permalink to &quot;IV. La Pratique des Cinq Typologies de la Civilisation Symbiotique&quot;">​</a></h2><p>Dans le processus de construction institutionnelle, différents plans et régions ont développé cinq typologies de la civilisation symbiotique selon leur propre histoire, culture et caractéristiques raciales :</p><table tabindex="0"><thead><tr><th>Typologie</th><th>Caractéristiques centrales</th><th>Régions typiques</th></tr></thead><tbody><tr><td>Type intensif d&#39;Asie de l&#39;Est</td><td>Haute densité de population, utilisation efficace des ressources, tradition collectiviste</td><td>Zone de peuplement oriental du Rén Zú</td></tr><tr><td>Type providence nordique</td><td>Garanties de haut niveau, liberté individuelle, harmonie entre l&#39;homme et la nature</td><td>Régions du Jīnglíng Zú (Race des Elfes) dans les zones de grand froid</td></tr><tr><td>Type pluraliste nord-américain</td><td>Cohabitation multiraciale, inclusion culturelle, piloté par l&#39;innovation</td><td>Zone multiraciale pluraliste du Nouveau Continent</td></tr><tr><td>Type social d&#39;Europe continentale</td><td>Économie sociale de marché, autonomie sectorielle, héritage culturel</td><td>Zone de renaissance des civilisations anciennes</td></tr><tr><td>Type de rattrapage en développement</td><td>Industrialisation rapide, priorité aux infrastructures, société apprenante</td><td>Régions tardives des anciennes zones de prédation</td></tr></tbody></table><p>Les cinq typologies ne sont pas mutuellement exclusives ; ce sont des pratiques institutionnelles aux accents différents sous le cadre unifié de la Constitution Symbiotique. Elles entretiennent entre elles des échanges et des concurrences étroits, enrichissant conjointement le contenu institutionnel de la civilisation symbiotique.</p><h2 id="v-la-construction-preliminaire-de-l-infrastructure-de-l-ancre" tabindex="-1">V. La Construction Préliminaire de l&#39;Infrastructure de l&#39;Ancre <a class="header-anchor" href="#v-la-construction-preliminaire-de-l-infrastructure-de-l-ancre" aria-label="Permalink to &quot;V. La Construction Préliminaire de l&#39;Infrastructure de l&#39;Ancre&quot;">​</a></h2><p>La Période d&#39;Établissement du Système Symbiotique fut aussi une période de construction à grande échelle de l&#39;infrastructure de l&#39;Ancre :</p><ul><li>L&#39;Ancre Principale Universelle de Premier Niveau a été achevée au début de l&#39;ère, devenant le noyau du réseau d&#39;Ancres de tout l&#39;univers.</li><li>Les Ancres Principales de Plan de Deuxième Niveau ont été progressivement déployées dans les plans principaux, la capacité de régulation énergétique au niveau du plan étant initialement formée.</li><li>Les Ancres Régionales de Troisième Niveau ont couvert les régions densément peuplées, fournissant un soutien énergétique à la vulgarisation de la culture.</li><li>Les Ancres Communautaires de Quatrième Niveau ont commencé un déploiement pilote, accumulant de l&#39;expérience pour la couverture globale ultérieure.</li></ul><p>La construction de l&#39;infrastructure de l&#39;Ancre suit le principe de « planification unifiée, construction par niveaux », garantissant une utilisation efficace des ressources et l&#39;équité de la couverture.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Période d&#39;Établissement du Système Symbiotique est « l&#39;ère de pose des fondations » de la Civilisation Symbiotique de l&#39;Ancre. En plusieurs centaines d&#39;années, elle a achevé la transformation institutionnelle fondamentale de l&#39;ordre prédateur de l&#39;Ère Pré-Ancre à l&#39;ordre symbiotique. L&#39;établissement du système juridique a fourni un cadre de règles à la civilisation ; la reconstruction des institutions sociales a fourni des garanties concrètes à tous les êtres ; la pratique des cinq typologies a fourni des voies pluralistes à l&#39;innovation institutionnelle ; et la construction de l&#39;infrastructure de l&#39;Ancre a posé la base matérielle du développement ultérieur. Lorsque le moment de l&#39;ouverture globale des Trois Cents Systèmes de Culture Originels est arrivé, la civilisation symbiotique était pleinement prête institutionnellement.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>72-锚点觉醒纪元 (L&#39;Ère de l&#39;Éveil de l&#39;Ancre)</li><li>74-三百套体系开放事件 (L&#39;Ouverture des Trois Cents Systèmes)</li><li>40-共生宪法总纲 (Lignes Directrices Générales de la Constitution Symbiotique)</li></ul>',31)])])}const b=t(a,[["render",o]]);export{p as __pageData,b as default};
